function onTabChanged(o, e) {
	var f = o.parentForm, c = f.getItemValue('tk') ? 'tk_1' : 'tk_bac_1';
	f.focusWhenTabChanged(['ma_dvcs', c]);
	&ReportSign.Filter.Active;

	onchange$Item$Bank(f.getItem('xem_tk_nh'));
}
/* <flatten type="Javascript"> */
function active$VoucherFilter$(f) {
	f._tabContainer.add_activeTabChanged(onTabChanged);
	f._tabContainer._loaded = true;
	f.add_onResponseComplete(on$Filter$ResponseComplete);

	if (f._convection) f._convection = null;

	changeLookupReadonly(f, 'ma_dvcs');
	if (f.getItemValue('tk')) f.getItem('tk_bac_1').disabled = f.getItem('xem_tat').disabled = f.getItem('tk_chi_tiet').disabled = true;
	else {
		var o = f.getItem('tk_1');
		$common.setVisible(o.a, false)
		o.disabled = true;
	}
}
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, x = f.getItemValue('mau_bc'), d1 = f.getItem('ngay1').value, d2 = f.getItem('ngay2').value;;
			g._hiddenFields = [
				{Fields: 'lk_no_ck, lk_co_ck', Value: (x == '001' || x == '002')},
				{Fields: 'no_dk_nt0, co_dk_nt0, lk_no_dk_nt, lk_co_dk_nt', Value: (x == '001' || x == '002' || x == '011' || x == '021' || x == '022')},
				{Fields: 'lk_no_ck_nt, lk_co_ck_nt', Value: (x == '001' || x == '002' || x == '011' || x == '021')},
				{Fields: 'no_dk0, co_dk0, lk_no_dk, lk_co_dk', Value: (x == '001' || x == '002' || x == '021' || x == '022')},
				{Fields: 'no_dk_nt, co_dk_nt, ps_no_nt, ps_co_nt, no_ck_nt, co_ck_nt', Value: (x == '001' || x == '011' || x == '012' || x == '021')},
				{Fields: 'no_dk, co_dk, ps_no, ps_co, no_ck, co_ck', Value: (x == '011' || x == '012')}
			];
			g._hiddenForms = [
				{Form: [2, 3, 4, 5, 8, 9, 10, 11, 15, 16, 17, 18, 21, 22, 23, 24], Value: (x == '001' || x == '002')},
				{Form: [0, 1, 4, 5, 6, 7, 10, 11, 13, 14, 17, 18, 19, 20, 23, 24], Value: (x == '011' || x == '012')},
				{Form: [0, 1, 2, 3, 6, 7, 8, 9, 13, 14, 15, 16, 19, 20, 21, 22], Value: (x == '021' || x == '022')}
			];
			g._alterTitle = [null, [['%d1', d1, true], ['%d2', d2, true]]];
			g._queryFilterString = getQueryFilterString(f, 'mau_bc, ngay1, ngay2, ma_dvcs, tk_1, xem_tk_nh, fcode4');
			g._$xem_tk_nh = f.getItemValue('xem_tk_nh');
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function onchange$Item(o) {
	var f = o.parentForm, s = o.field.Name, v = (s == 'tk_bac');
	var a = ['tk', 'tk_bac', 'xem_tat', 'tk_chi_tiet'];
	if ((s != 'xem_tat' ) && (s != 'tk_chi_tiet')) f.getItem('xem_tat').disabled = f.getItem('tk_chi_tiet').disabled = !v;
	$common.setVisible(f.getItem('tk_1').a, s == 'tk');
	for (var i = 0; i < a.length; i++) {
		if (f.getItem(a[i]) != o) f.getItem(a[i]).checked = false;
		 else f.getItem(s).checked = true;
	}
	if (s == 'tk') {
		setItemDisable(f.getItem('tk'));
		f.getItem('tk_bac_1').value = '99';
	}
	else {f.getItem('tk_1').value = ''; f.getItem('ten_tk%l').value = '';}

	if (s == 'tk_bac') {
		setItemDisable(f.getItem('tk_bac'));
		f.getItem('xem_tat').checked = true;
	}
	if (s == 'xem_tat') f.getItem('tk_bac').checked = true;
	if (s == 'tk_chi_tiet') f.getItem('tk_bac').checked = true;
	f.getItem(f.getItemValue('tk') ? 'tk_1' : 'tk_bac_1').focus();
}
function setItemDisable(o) {
	var f = o.parentForm, s = o.field.Name, a = ['tk_1', 'tk_bac_1'];
	for (var i = 0; i < a.length; i++) {f.getItem(a[i]).disabled = ((s + '_1') != a[i]);}
}
function onchange$Item$Bank(o) {
	var f = o.parentForm;
	f.getItem('fcode4').disabled = !f.getItem('xem_tk_nh').checked;
	$common.setVisible(f.getItem('fcode4').a, f.getItem('xem_tk_nh').checked);

	if (f.getItem('fcode4').disabled) f.setItemControlBehavior('fcode4', '', '', null);
}
